#!/usr/bin/env python3
"""Build a self-contained Chinese viewer of source-bound measured tensor-TMA evidence."""
import argparse
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEFAULTS = [ROOT / f"out/research/modal/20261023-{gpu}-tma-full-v1/artifacts/tma-full/summary.json" for gpu in ("b200", "h100")]


def digest(data):
    return hashlib.sha256(data).hexdigest()


def load_suite(path):
    raw = path.read_bytes()
    suite = json.loads(raw)
    if suite.get("format") != "gpu-tensor-tma-version-suite-v1" or suite.get("status") != "completed":
        raise ValueError(f"Unsupported or incomplete suite: {path}")
    source_path = path.parent / "tma_version_probe.cu"
    source_raw = source_path.read_bytes()
    source_sha = digest(source_raw)
    if source_sha != suite["source_hashes"][source_path.name]:
        raise ValueError("Bound source hash mismatch")
    runs = []
    for run in suite["runs"]:
        if run.get("format") != "gpu-tensor-tma-version-probe-v1" or run.get("device_status") != 0:
            raise ValueError("Unsupported probe or device failure; no numerical claims allowed")
        raw_path = path.parent / run["recordRef"]["path"]
        if raw_path.parent.resolve() != path.parent.resolve():
            raise ValueError("Raw record outside suite directory")
        saved = raw_path.read_bytes()
        if digest(saved) != run["recordRef"]["sha256"]:
            raise ValueError("Raw stdout hash mismatch")
        original = json.loads(saved.decode().splitlines()[run["recordRef"]["json_line"] - 1])
        for key in ("output", "reference", "observed_generations", "expected_generations", "shape", "variant", "generations", "seed"):
            if original[key] != run[key]:
                raise ValueError(f"Raw/summary field mismatch: {key}")
        expected_count = run["shape"][0] * run["shape"][1] * run["generations"]
        if any(len(run[key]) != expected_count for key in ("output", "reference", "observed_generations", "expected_generations")):
            raise ValueError("Output count mismatch")
        if sum(a != b for a, b in zip(run["output"], run["reference"])) != run["correctness"]["value_mismatches"]:
            raise ValueError("Value mismatch count mismatch")
        if sum(a != b for a, b in zip(run["observed_generations"], run["expected_generations"])) != run["correctness"]["version_mismatches"]:
            raise ValueError("Version mismatch count mismatch")
        for i, event in enumerate(run["events"]):
            if event["recordRef"]["source_sha256"] != source_sha or event["recordRef"]["sha256"] != run["recordRef"]["sha256"]:
                raise ValueError("Event provenance mismatch")
            if {k: v for k, v in event.items() if k != "recordRef"} != original["events"][i]:
                raise ValueError("Raw/summary event mismatch")
            if event["recordRef"]["json_pointer"] != f"/events/{i}":
                raise ValueError("Event raw pointer mismatch")
        runs.append(run)
    checks = {"runs": len(runs), "output_elements": sum(len(r["output"]) for r in runs),
              "successful_wait_observations": sum(e["role"] == "wait_returned_true" and e["wait_success"] for r in runs for e in r["events"]),
              "value_mismatches": sum(r["correctness"]["value_mismatches"] for r in runs),
              "version_mismatches": sum(r["correctness"]["version_mismatches"] for r in runs)}
    count_map = {"runs": "normal_runs", "output_elements": "normal_output_elements", "successful_wait_observations": "successful_wait_observations", "value_mismatches": "normal_value_mismatches", "version_mismatches": "normal_version_mismatches"}
    if any(checks[key] != suite["counts"][source_key] for key, source_key in count_map.items()):
        raise ValueError("Aggregate count mismatch")
    return {"id": "B200" if "B200" in suite["gpu_identity"] else "H100" if "H100" in suite["gpu_identity"] else suite["gpu_identity"],
            "gpu_identity": suite["gpu_identity"], "compile_target": suite["compile_target"], "scope": suite["scope"],
            "summary_path": str(path.relative_to(ROOT)) if path.is_relative_to(ROOT) else str(path),
            "summary_sha256": digest(raw), "source_sha256": source_sha, "source_name": source_path.name,
            "source": source_raw.decode(), "contract": suite["operator_contract"], "counts": suite["counts"],
            "verified_counts": checks, "runs": runs}


