def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--summary", type=Path, action="append")
    parser.add_argument("--out", type=Path, default=ROOT / "out/research/modern-viewer")
    parser.add_argument("--tcgen-summary", type=Path, default=ROOT / "out/research/modal/20261023-b200-tcgen05-full-v1/artifacts/tcgen05-suite/summary.json")
    args = parser.parse_args()
    suites = [load_suite(p.resolve()) for p in (args.summary or DEFAULTS)]
    if len({s["id"] for s in suites}) != len(suites):
        raise ValueError("Duplicate GPU suite IDs")
    data = {"format": "measured-tensor-tma-viewer-v1", "suites": suites,
            "scope": "Measured tensor TMA full suites only; no tcgen05 smoke/full data included"}
    serialized = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c")
    html = HTML.replace("__DATA__", serialized)
    args.out.mkdir(parents=True, exist_ok=True)
    target = args.out / "modern-evidence.html"
    tc_data = load_tcgen(args.tcgen_summary.resolve()) if args.tcgen_summary.exists() else None
    if tc_data:
        html = html.replace('</header>', '</header><p><a class="link" href="tcgen05-evidence.html">另看 B200 tcgen05：完整 generation 不同但 tag 低位相同 →</a></p>', 1)
        tc_json = json.dumps(tc_data, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c")
        tc_html = TC_HTML.replace("__STYLE__", HTML.split("<style>")[1].split("</style>")[0]).replace("__DATA__", tc_json)
        (args.out / "tcgen05-evidence.html").write_text(tc_html)
    target.write_text(html)
    manifest = {"generated_utc": datetime.now(timezone.utc).isoformat(), "html": target.name,
                "html_sha256": digest(target.read_bytes()), "renderer_sha256": digest(Path(__file__).read_bytes()),
                "runs": sum(len(s["runs"]) for s in suites), "output_elements": sum(s["verified_counts"]["output_elements"] for s in suites),
                "source_and_raw_hashes_verified": True, "raw_summary_fields_verified": True,
                "suites": [{k: s[k] for k in ("id", "summary_path", "summary_sha256", "source_sha256", "verified_counts")} for s in suites],
                "limitations": ["Source-bound ordering, not a measured hardware timeline", "Actual transported tags are separate from source-derived expectations", "TMA page excludes tcgen05; optional separate TC representative page; no agent/user-study claims"],
                "tcgen05_representatives": {"included": bool(tc_data), "runs": len(tc_data["runs"]) if tc_data else 0, "selection": tc_data["selection"] if tc_data else None, "source_sha256": tc_data["source_sha256"] if tc_data else None, "summary_sha256": tc_data["summary_sha256"] if tc_data else None, "html_sha256": digest((args.out / "tcgen05-evidence.html").read_bytes()) if tc_data else None}}
    (args.out / "render-manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps(manifest, ensure_ascii=False))


if __name__ == "__main__":
    main()
